  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-bg: #f8f9fb;
  --color-surface: #ffffff;
  --color-border: #e2e6ec;
  --color-text: #1a1d23;
  --color-text-muted: #5a6070;
  --color-accent: #5b6af0;
  --color-accent-hover: #4655e0;
  --color-accent-light: #eef0fd;
  --color-focus-ring: #5b6af0;
  --radius-card: 14px;
  --radius-btn: 8px;
  --shadow-card: 0 2px 12px rgba(0, 0, 0, 0.07);
  --transition: 200ms ease;
  --font: "Inter", "Segoe UI", system-ui, sans-serif;
}

body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-btn);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
}

/* Page header */
.page-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 3rem;
}

.page-header__eyebrow {
  display: inline-block;
  background: var(--color-accent-light);
  color: var(--color-accent);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 0.3rem 0.85rem;
  border-radius: 100px;
  margin-bottom: 1rem;
}

.page-header h1 {
  font-size: clamp(1.75rem, 5vw, 2.75rem);
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--color-text);
  margin-bottom: 0.75rem;
}

.page-header__subtitle {
  font-size: 1.0625rem;
  color: var(--color-text-muted);
}

/* FAQ container */
.faq {
  max-width: 680px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* Single FAQ item */
.example {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  overflow: hidden;
  transition: box-shadow var(--transition), border-color var(--transition);
}

.example:has(.faq-trigger[aria-expanded="true"]) {
  border-color: var(--color-accent);
  box-shadow: 0 4px 20px rgba(91, 106, 240, 0.12);
}

/* Trigger button */
.faq-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.125rem 1.375rem;
  background: none;
  border: none;
  cursor: pointer;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  text-align: left;
  border-radius: var(--radius-card);
  transition: background var(--transition), color var(--transition);
}

.faq-trigger:hover {
  background: var(--color-accent-light);
  color: var(--color-accent);
}

.faq-trigger:focus-visible {
  outline: 2.5px solid var(--color-focus-ring);
  outline-offset: -2.5px;
  border-radius: var(--radius-card);
}

.faq-trigger[aria-expanded="true"] {
  color: var(--color-accent);
  border-radius: var(--radius-card) var(--radius-card) 0 0;
}

.faq-trigger__question {
  flex: 1;
}

/* Chevron icon */
.faq-trigger__icon {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  color: var(--color-text-muted);
  transition: transform var(--transition), color var(--transition);
}

.faq-trigger[aria-expanded="true"] .faq-trigger__icon {
  transform: rotate(180deg);
  color: var(--color-accent);
}

/* Answer panel */
.details {
  overflow: hidden;
  max-height: 0;
  transition: max-height 280ms cubic-bezier(0.4, 0, 0.2, 1);
}

.details[aria-hidden="false"] {
  max-height: 600px;
}

.details__inner {
  padding: 0 1.375rem 1.25rem;
  border-top: 1px solid var(--color-border);
  color: var(--color-text-muted);
  font-size: 0.9375rem;
  line-height: 1.75;
}

.details__inner p + p {
  margin-top: 0.75rem;
}

/* Responsive */
@media (max-width: 480px) {
  .faq-trigger {
    padding: 1rem 1.125rem;
  }
  .details__inner {
    padding: 0 1.125rem 1.125rem;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .details,
  .faq-trigger__icon,
  .faq-trigger,
  .example {
    transition: none;
  }
}

/* Forced colors */
@media (forced-colors: active) {
  .example {
    border: 2px solid ButtonBorder;
  }
  .faq-trigger {
    color: ButtonText;
    forced-color-adjust: none;
  }
  .faq-trigger:hover,
  .faq-trigger[aria-expanded="true"] {
    background: Highlight;
    color: HighlightText;
  }
  .faq-trigger__icon {
    fill: currentColor;
  }
}
