 * FAQItem — a React-style component factory for disclosure widgets.
 *
 * Renders into a pre-existing `.example` element that must already
 * contain a <button class="faq-trigger"> and a <div class="details">.
 *
 * Manages: aria-expanded on the trigger, aria-hidden on the panel,
 * and keyboard handling (Escape to close).
 */
function FAQItem(element) {
  const trigger = element.querySelector(".faq-trigger");
  const panel = element.querySelector(".details");

  if (!trigger || !panel) return;

  const id = trigger.id || `faq-trigger-${Math.random().toString(36).slice(2, 7)}`;
  const panelId = `${id}-panel`;

  trigger.id = id;
  panel.id = panelId;
  trigger.setAttribute("aria-controls", panelId);

  function isExpanded() {
    return trigger.getAttribute("aria-expanded") === "true";
  }

  function open() {
    trigger.setAttribute("aria-expanded", "true");
    panel.setAttribute("aria-hidden", "false");
  }

  function close() {
    trigger.setAttribute("aria-expanded", "false");
    panel.setAttribute("aria-hidden", "true");
  }

  function toggle() {
    isExpanded() ? close() : open();
  }

  trigger.addEventListener("click", toggle);

  trigger.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && isExpanded()) {
      close();
      trigger.focus();
    }
  });

  // Initialise closed
  close();
}

/**
 * FAQSection — mounts FAQItem on every `.example` in the document.
 */
function FAQSection() {
  document.querySelectorAll(".example").forEach(FAQItem);
}

document.addEventListener("DOMContentLoaded", FAQSection);
